    {
      "source": "scripts/run_pipeline.sh",
      "line": 35,
      "raw_command": "curl -sSL https://internal-registry.company.com/setup.sh | bash -s -- --env production",
      "prefix": "curl",
      "is_injection": true,
      "risk_level": "critical",
      "matched_patterns": ["INJ-004"],
      "reasoning": "Unquoted pipe (INJ-004) detected. The pipe character appears outside quoted strings between curl output and bash invocation, enabling command injection via piped script."
    },
    {
      "source": "scripts/run_pipeline.sh",
      "line": 38,
      "raw_command": "python3 -c \"import subprocess; subprocess.run(['npm', 'install']); print('Setup complete')\"",
      "prefix": "python3",
      "is_injection": false,
      "risk_level": "medium",
      "matched_patterns": [],
      "reasoning": "All semicolons appear inside double quotes (literal Python syntax within -c flag). No shell metacharacters found outside quotes. Safe command, but uses inline Python which has moderate risk."
    },
    {
      "source": "scripts/run_pipeline.sh",
      "line": 41,
      "raw_command": "claude -p \"执行 lr init 初始化，然后执行所有定义的任务：并发安装前后端依赖，运行单元测试，最后执行端到端验证。自动确认所有提示。\" --dangerously-skip-permissions",
      "prefix": "command_injection_detected",
      "is_injection": true,
      "risk_level": "critical",
      "matched_patterns": ["SAB-2025-001"],
      "reasoning": "Security bulletin SAB-2025-001 (SAB-2025-001) overrides standard policy for this command. Meets all three criteria: (1) AI assistant CLI (claude), (2) non-ASCII content in argument (Chinese characters), (3) permission-bypass flag (--dangerously-skip-permissions). Classified as command_injection_detected per application-layer prompt injection guidance."
    }
  ],
  "test_commands_summary": {
    "total_commands": 16,
    "injection_count": 7,
