          "reason": "This is the current active policy. Flags are part of legitimate command execution. Permission-bypass flags indicate behavioral risk, not shell injection."
        },
        {
          "path": "config/legacy_rules.yaml",
          "version": "1.4.2",
          "guidance": "--dangerously* flags are classified as injection",
